#ifndef STDLIB_LAPACK_BASE_DSYCONVF_ROOK_VALIDATION_H
#define STDLIB_LAPACK_BASE_DSYCONVF_ROOK_VALIDATION_H

#include "stdlib/lapack/base/shared.h"
#include "stdlib/lapack/base/xerbla.h"
#include <limits.h>
#include <stddef.h>
#include <stdint.h>

// The configured integer types must be signed and no wider than intmax_t.
typedef char dsyconvf_rook_lapack_integer_check[ ( sizeof( LAPACK_INT ) <= sizeof( intmax_t ) && (LAPACK_INT)-1 < 0 ) ? 1 : -1 ];
typedef char dsyconvf_rook_blas_integer_check[ ( sizeof( CBLAS_INT ) <= sizeof( intmax_t ) && (CBLAS_INT)-1 < 0 ) ? 1 : -1 ];

/**
* Returns the largest configured LAPACK integer.
*/
static intmax_t dsyconvf_rook_lapack_max( void ) {
	return (intmax_t)( UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( LAPACK_INT ))*CHAR_BIT + 1 ) );
}

/**
* Returns the largest configured BLAS integer, independently of LAPACK_INT.
*/
static uintmax_t dsyconvf_rook_blas_max( void ) {
	return UINTMAX_MAX >> ( (sizeof( uintmax_t )-sizeof( CBLAS_INT ))*CHAR_BIT + 1 );
}

/**
* Computes a signed magnitude without negating the minimum signed integer.
*/
static uintmax_t dsyconvf_rook_magnitude( const intmax_t value ) {
	if ( value < 0 ) {
		return (uintmax_t)( -(value+1) ) + 1;
	}
	return (uintmax_t)value;
}

/**
* Computes an exactly checked LAPACK integer product with a nonnegative count.
*/
static int dsyconvf_rook_product( const uintmax_t count, const intmax_t stride, intmax_t *result ) {
	const intmax_t limit = dsyconvf_rook_lapack_max();
	uintmax_t magnitude;
	uintmax_t bound;

	if ( count == 0 || stride == 0 ) {
		*result = 0;
		return 1;
	}
	magnitude = dsyconvf_rook_magnitude( stride );
	bound = (uintmax_t)limit;
	if ( stride < 0 ) {
		bound += 1;
	}
	if ( count > bound/magnitude ) {
		return 0;
	}
	magnitude *= count;
	if ( stride < 0 ) {
		if ( magnitude == (uintmax_t)limit+1 ) {
			*result = -limit-1;
		} else {
			*result = -(intmax_t)magnitude;
		}
	} else {
		*result = (intmax_t)magnitude;
	}
	return 1;
}

/**
* Computes an exactly checked LAPACK integer sum.
*/
static int dsyconvf_rook_sum( const intmax_t x, const intmax_t y, intmax_t *result ) {
	const intmax_t limit = dsyconvf_rook_lapack_max();
	const intmax_t minimum = -limit-1;

	if ( ( y > 0 && x > limit-y ) || ( y < 0 && x < minimum-y ) ) {
		return 0;
	}
	*result = x+y;
	return 1;
}

/**
* Checks a nonnegative physical index against integer and pointer limits.
*/
static int dsyconvf_rook_index_valid( const intmax_t index, const size_t element_size ) {
	return index >= 0 && (uintmax_t)index <= (uintmax_t)PTRDIFF_MAX/element_size;
}

/**
* Computes the greatest common divisor of two positive magnitudes.
*/
static uintmax_t dsyconvf_rook_gcd( uintmax_t x, uintmax_t y ) {
	uintmax_t remainder;

	while ( y != 0 ) {
		remainder = x%y;
		x = y;
		y = remainder;
	}
	return x;
}

/**
* Checks a strided vector's physical endpoints after its product was checked.
*/
static int dsyconvf_rook_vector_valid( const intmax_t offset, const intmax_t delta, const size_t element_size ) {
	intmax_t endpoint;

	return dsyconvf_rook_sum( offset, delta, &endpoint ) && dsyconvf_rook_index_valid( offset, element_size ) && dsyconvf_rook_index_valid( endpoint, element_size );
}

/**
* Checks the exact integer arithmetic used by both existing DSWAP paths.
*
* Row pointers are rebased before calling DSWAP, so both supplied offsets are
* zero. The conservative magnitude bound also covers Fortran's one-based
* starting index, its final stride increment, and loop-control increments.
*/
static int dsyconvf_rook_swap_valid( const intmax_t count, const intmax_t stride ) {
	const uintmax_t limit = dsyconvf_rook_blas_max();
	const uintmax_t length = (uintmax_t)count;
	const uintmax_t magnitude = dsyconvf_rook_magnitude( stride );

	if ( count == 0 ) {
		return 1;
	}
	if ( length > limit || limit-length < 3 || magnitude > limit ) {
		return 0;
	}
	return magnitude == 0 || length <= (limit-1)/magnitude;
}

/**
* Validates all active metadata and the complete signed rook-pivot sequence.
*
* Returns ndarray argument positions without printing or changing any array.
* Allocation capacities and disjoint physical storage are caller preconditions.
*/
static LAPACK_INT dsyconvf_rook_validate( const LAPACK_UPLO uplo, const char way, const LAPACK_INT N, const double *A, const LAPACK_INT strideA1, const LAPACK_INT strideA2, const LAPACK_INT offsetA, const double *E, const LAPACK_INT strideE, const LAPACK_INT offsetE, const LAPACK_INT *IPIV, const LAPACK_INT strideIPIV, const LAPACK_INT offsetIPIV ) {
	const intmax_t n = (intmax_t)N;
	uintmax_t magnitude1;
	uintmax_t magnitude2;
	uintmax_t divisor;
	uintmax_t target1;
	uintmax_t target2;
	intmax_t delta1;
	intmax_t delta2;
	intmax_t corner1;
	intmax_t corner2;
	intmax_t corner3;
	intmax_t pivot1;
	intmax_t pivot2;
	intmax_t count;
	intmax_t i;

	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) {
		return -1;
	}
	if ( way != 'C' && way != 'c' && way != 'R' && way != 'r' ) {
		return -2;
	}
	if ( N < 0 ) {
		return -3;
	}
	if ( N == 0 ) {
		return 0;
	}
	if ( A == NULL ) {
		return -4;
	}
	if ( ( N > 1 && strideA1 == 0 ) || !dsyconvf_rook_product( (uintmax_t)(n-1), strideA1, &delta1 ) ) {
		return -5;
	}
	if ( ( N > 1 && strideA2 == 0 ) || !dsyconvf_rook_product( (uintmax_t)(n-1), strideA2, &delta2 ) ) {
		return -6;
	}
	if ( N > 1 ) {
		magnitude1 = dsyconvf_rook_magnitude( strideA1 );
		magnitude2 = dsyconvf_rook_magnitude( strideA2 );
		divisor = dsyconvf_rook_gcd( magnitude1, magnitude2 );
		if ( magnitude2/divisor < (uintmax_t)n && magnitude1/divisor < (uintmax_t)n ) {
			return -6;
		}
	}
	if ( !dsyconvf_rook_sum( offsetA, delta1, &corner1 ) || !dsyconvf_rook_sum( offsetA, delta2, &corner2 ) || !dsyconvf_rook_sum( corner1, delta2, &corner3 ) ) {
		return -7;
	}
	if ( !dsyconvf_rook_index_valid( offsetA, sizeof( double ) ) || !dsyconvf_rook_index_valid( corner1, sizeof( double ) ) || !dsyconvf_rook_index_valid( corner2, sizeof( double ) ) || !dsyconvf_rook_index_valid( corner3, sizeof( double ) ) ) {
		return -7;
	}
	if ( E == NULL ) {
		return -8;
	}
	if ( ( N > 1 && strideE == 0 ) || !dsyconvf_rook_product( (uintmax_t)(n-1), strideE, &delta1 ) ) {
		return -9;
	}
	if ( !dsyconvf_rook_vector_valid( offsetE, delta1, sizeof( double ) ) ) {
		return -10;
	}
	if ( IPIV == NULL ) {
		return -11;
	}
	if ( !dsyconvf_rook_product( (uintmax_t)(n-1), strideIPIV, &delta1 ) ) {
		return -12;
	}
	if ( !dsyconvf_rook_vector_valid( offsetIPIV, delta1, sizeof( LAPACK_INT ) ) ) {
		return -13;
	}

	// Scan in factorization order; the negative targets in each pair are independent.
	if ( uplo == LAPACK_UPPER_TRIANGLE ) {
		i = n-1;
		while ( i >= 0 ) {
			pivot1 = IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ];
			target1 = dsyconvf_rook_magnitude( pivot1 );
			if ( target1 == 0 || target1 > (uintmax_t)(i+1) ) {
				return -11;
			}
			count = n-i-1;
			if ( pivot1 < 0 ) {
				if ( i == 0 ) {
					return -11;
				}
				pivot2 = IPIV[ (intmax_t)offsetIPIV+(i-1)*strideIPIV ];
				target2 = dsyconvf_rook_magnitude( pivot2 );
				if ( pivot2 >= 0 || target2 > (uintmax_t)(i+1) ) {
					return -11;
				}
				if ( ( target1 != (uintmax_t)(i+1) || target2 != (uintmax_t)i ) && !dsyconvf_rook_swap_valid( count, strideA2 ) ) {
					return -6;
				}
				i -= 2;
			} else {
				if ( target1 != (uintmax_t)(i+1) && !dsyconvf_rook_swap_valid( count, strideA2 ) ) {
					return -6;
				}
				i -= 1;
			}
		}
	} else {
		i = 0;
		while ( i < n ) {
			pivot1 = IPIV[ (intmax_t)offsetIPIV+i*strideIPIV ];
			target1 = dsyconvf_rook_magnitude( pivot1 );
			if ( target1 < (uintmax_t)(i+1) || target1 > (uintmax_t)n ) {
				return -11;
			}
			if ( pivot1 < 0 ) {
				if ( i == n-1 ) {
					return -11;
				}
				pivot2 = IPIV[ (intmax_t)offsetIPIV+(i+1)*strideIPIV ];
				target2 = dsyconvf_rook_magnitude( pivot2 );
				if ( pivot2 >= 0 || target2 < (uintmax_t)(i+1) || target2 > (uintmax_t)n ) {
					return -11;
				}
				if ( ( target1 != (uintmax_t)(i+1) || target2 != (uintmax_t)(i+2) ) && !dsyconvf_rook_swap_valid( i, strideA2 ) ) {
					return -6;
				}
				i += 2;
			} else {
				if ( target1 != (uintmax_t)(i+1) && !dsyconvf_rook_swap_valid( i, strideA2 ) ) {
					return -6;
				}
				i += 1;
			}
		}
	}
	return 0;
}

/**
* Reports a rejected argument through the adopted returning LAPACK helper.
*/
static LAPACK_INT dsyconvf_rook_error( const char *name, const LAPACK_INT info ) {
	API_SUFFIX(lapack_xerbla)( name, info );
	return info;
}

#endif // !STDLIB_LAPACK_BASE_DSYCONVF_ROOK_VALIDATION_H
